119: fn run_concurrent_benchmark(processor: &Arc<PaymentProcessor>) {
120:     let thread_count = 4;
121:     let tx_per_thread = 250;
122:     let mut handles = Vec::with_capacity(thread_count);
123: 
124:     for t_idx in 0..thread_count {
125:         let proc = Arc::clone(processor);
126:         handles.push(std::thread::spawn(move || {
127:             for i in 0..tx_per_thread {
128:                 let amount = if i % 10 == 0 { 150_000 } else { 1_000 };
129:                 let tx = PaymentTx {
130:                     id: (t_idx * 10_000 + i) as u64,
131:                     account_id: (t_idx + 1) as u64,
132:                     amount_cents: amount,
133:                     currency: Currency::Eur,
134:                     status: TxStatus::Initiated,
135:                 };
136:                 let out = proc.process(tx);
137:                 assert_eq!(out.currency, Currency::Eur);
138:             }
139:         }));
140:     }
141: 
142:     for h in handles {
143:         let _ = h.join();
144:     }
145: }
