148: #[test]
149: fn pay_ptp_benchmark() {
150:     let slot = "pay_ptp_benchmark";
151:     assert_eq!(slot, "pay_ptp_benchmark");
152: 
153:     run_validation_suite();
154: 
155:     let processor = Arc::new(PaymentProcessor::new(100_000));
156:     run_concurrent_benchmark(&processor);
157: 
158:     let settled = processor.settled_count.load(Ordering::SeqCst);
159:     let rejected = processor.rejected_count.load(Ordering::SeqCst);
160:     let total = settled + rejected;
161: 
162:     assert_eq!(total, 1_000);
163:     assert_eq!(rejected, 100);
164:     assert_eq!(settled, 900);
165:     assert_eq!(processor.total_volume_cents.load(Ordering::SeqCst), 900 * 1_000);
166: }
