19: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
20: pub enum PacketType {
21:     Data,
22:     Ack,
23:     Heartbeat,
24:     Control,
25:     Reset,
26: }
27: 
28: impl PacketType {
29:     pub fn from_u8(val: u8) -> Option<Self> {
30:         match val {
31:             1 => Some(Self::Data),
32:             2 => Some(Self::Ack),
33:             3 => Some(Self::Heartbeat),
34:             4 => Some(Self::Control),
35:             5 => Some(Self::Reset),
36:             _ => None,
37:         }
38:     }
39: 
40:     pub fn to_u8(self) -> u8 {
41:         match self {
42:             Self::Data => 1,
43:             Self::Ack => 2,
44:             Self::Heartbeat => 3,
45:             Self::Control => 4,
46:             Self::Reset => 5,
47:         }
48:     }
49: }
50: 
51: pub fn compute_checksum(bytes: &[u8]) -> u32 {
52:     let mut sum1: u32 = 1;
53:     let mut sum2: u32 = 0;
54:     for &b in bytes {
55:         sum1 = (sum1 + b as u32) % 65521;
56:         sum2 = (sum2 + sum1) % 65521;
57:     }
58:     (sum2 << 16) | sum1
59: }
60: 
61: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
62: pub struct PacketHeader<'a> {
63:     pub magic: &'a [u8],
64:     pub version: u8,
65:     pub packet_type: PacketType,
66:     pub flags: u8,
67:     pub sequence_id: u32,
68:     pub payload_len: u32,
69:     pub checksum: u32,
70: }
