72: fn validate_prefix<'a>(buf: &'a [u8]) -> Result<(), ParseError<'a>> {
73:     if buf.len() < HEADER_SIZE {
74:         return Err(ParseError::BufferTooSmall { needed: HEADER_SIZE, available: buf.len() });
75:     }
76:     if &buf[0..4] != MAGIC {
77:         return Err(ParseError::InvalidHeader { header: &buf[0..4], offset: 0 });
78:     }
79:     if buf[4] != PROTOCOL_VERSION {
80:         return Err(ParseError::UnexpectedByte {
81:             expected: PROTOCOL_VERSION,
82:             found: buf[4],
83:             offset: 4,
84:         });
85:     }
86:     Ok(())
87: }
