89: fn verify_checksum_field<'a>(checksum: u32, buf: &'a [u8]) -> Result<(), ParseError<'a>> {
90:     if checksum != 0 {
91:         let computed = compute_checksum(&buf[0..16]);
92:         if checksum != computed {
93:             return Err(ParseError::ChecksumMismatch { expected: checksum, computed, offset: 16 });
94:         }
95:     }
96:     Ok(())
97: }
