11: #[derive(Debug, Clone, PartialEq, Eq)]
12: pub struct CycleTrace {
13:     pub path: Vec<NodeId>,
14: }
15: 
16: impl CycleTrace {
17:     pub fn new(path: Vec<NodeId>) -> Self {
18:         Self { path }
19:     }
20: 
21:     pub fn len(&self) -> usize {
22:         self.path.len()
23:     }
24: 
25:     pub fn is_empty(&self) -> bool {
26:         self.path.is_empty()
27:     }
28: 
29:     pub fn is_closed(&self) -> bool {
30:         self.path.len() >= 2 && self.path.first() == self.path.last()
31:     }
32: 
33:     pub fn cycle_length(&self) -> usize {
34:         if self.is_closed() {
35:             self.path.len() - 1
36:         } else {
37:             self.path.len()
38:         }
39:     }
40: 
41:     pub fn contains(&self, id: &NodeId) -> bool {
42:         self.path.contains(id)
43:     }
44: 
45:     pub fn canonical(&self) -> Vec<NodeId> {
46:         if self.path.len() <= 1 {
47:             return self.path.clone();
48:         }
49:         let nodes = if self.is_closed() {
50:             &self.path[..self.path.len() - 1]
51:         } else {
52:             &self.path[..]
53:         };
54:         if nodes.is_empty() {
55:             return Vec::new();
56:         }
57:         let min_pos = nodes
58:             .iter()
59:             .enumerate()
60:             .min_by_key(|&(_, id)| id)
61:             .map(|(idx, _)| idx)
62:             .unwrap_or(0);
63:         let mut canon = Vec::with_capacity(nodes.len() + 1);
64:         canon.extend_from_slice(&nodes[min_pos..]);
65:         canon.extend_from_slice(&nodes[..min_pos]);
66:         canon.push(canon[0]);
67:         canon
68:     }
69: }
