71: #[derive(Debug, Default)]
72: pub struct CycleTracer;
73: 
74: impl CycleTracer {
75:     pub fn has_cycle(store: &DagNodeStore) -> bool {
76:         Self::find_cycle(store).is_some()
77:     }
78: 
79:     pub fn find_cycle(store: &DagNodeStore) -> Option<CycleTrace> {
80:         let mut visited = BTreeSet::new();
81:         let mut on_stack = BTreeSet::new();
82:         let mut path = Vec::new();
83: 
84:         for id in store.node_ids() {
85:             if !visited.contains(&id) {
86:                 if let Some(cycle) = Self::dfs_backtrack(
87:                     store,
88:                     id,
89:                     &mut visited,
90:                     &mut on_stack,
91:                     &mut path,
92:                 ) {
93:                     return Some(cycle);
94:                 }
95:             }
96:         }
97:         None
98:     }
99: 
100:     pub fn trace_cycle_from(store: &DagNodeStore, start: NodeId) -> Option<CycleTrace> {
101:         let mut visited = BTreeSet::new();
102:         let mut on_stack = BTreeSet::new();
103:         let mut path = Vec::new();
104:         Self::dfs_backtrack(store, start, &mut visited, &mut on_stack, &mut path)
105:     }
106: 
107:     fn dfs_backtrack(
108:         store: &DagNodeStore,
109:         current: NodeId,
110:         visited: &mut BTreeSet<NodeId>,
111:         on_stack: &mut BTreeSet<NodeId>,
112:         path: &mut Vec<NodeId>,
113:     ) -> Option<CycleTrace> {
114:         visited.insert(current);
115:         on_stack.insert(current);
116:         path.push(current);
117: 
118:         let deps = store.dependencies_of(&current).unwrap_or_default();
119:         for dep in deps {
120:             if on_stack.contains(&dep) {
121:                 let pos = path.iter().position(|&n| n == dep).unwrap_or(0);
122:                 let mut cycle_path = path[pos..].to_vec();
123:                 cycle_path.push(dep);
124:                 return Some(CycleTrace::new(cycle_path));
125:             }
126:             if !visited.contains(&dep) {
127:                 if let Some(cycle) = Self::dfs_backtrack(
128:                     store,
129:                     dep,
130:                     visited,
131:                     on_stack,
132:                     path,
133:                 ) {
134:                     return Some(cycle);
135:                 }
136:             }
137:         }
138: 
139:         path.pop();
140:         on_stack.remove(&current);
141:         None
142:     }
143: 
144:     pub fn find_all_cycles(store: &DagNodeStore) -> Vec<CycleTrace> {
145:         let mut results: Vec<CycleTrace> = Vec::new();
146:         let mut seen_canonical = BTreeSet::new();
147: 
148:         for id in store.node_ids() {
149:             let mut visited = BTreeSet::new();
150:             let mut on_stack = BTreeSet::new();
151:             let mut path = Vec::new();
152:             if let Some(cycle) = Self::dfs_backtrack(
153:                 store,
154:                 id,
155:                 &mut visited,
156:                 &mut on_stack,
157:                 &mut path,
158:             ) {
159:                 let canon = cycle.canonical();
160:                 if seen_canonical.insert(canon) {
161:                     results.push(cycle);
162:                 }
163:             }
164:         }
165:         results
166:     }
167: }
